test('invoiceTotals: tier and explicit discounts combined', () => {
  // C-003 is silver (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // 5 x 9500 = 47500, 2.5% = 1188
      { sku: 'DES-HOUR', qty: 3, discountPercent: 10 }, // 3 x 8500 = 25500, 10% = 2550
    ],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  // Subtotal: 47500 + 25500 = 73000
  // Discount: 1188 + 2550 = 3738
  // VAT: (47500-1188)*21% + (25500-2550)*21% = 46312*21% + 22950*21% = 9726 + 4820 = 14546
  // Total: 73000 - 3738 + 14546 = 83808
  assert.equal(totals.subtotal, 73000);
  assert.equal(totals.discount, 3738);
  assert.equal(totals.vat, 14546);
  assert.equal(totals.total, 83808);
});

